import {MAX_WAVE_BINS,normalizeWaveform} from './audio/waveform.js';
export const VERSION = 1;
export const COLORS = ['#73d9f8','#ffb574','#b6a0ff','#89e3bc'];
export const LETTERS = ['A','B','C','D'];
export const CUE_COLORS = ['#ed7d92','#ffa967','#e3ce66','#87dbaa','#69cfe0','#859cfa','#ba90e9','#de8ad1'];
export const clamp = (v,lo,hi) => Math.max(lo,Math.min(hi,Number.isFinite(Number(v))?Number(v):lo));
export const mod = (a,n) => ((a%n)+n)%n;
export const time = s => {s=Math.max(0,Number(s)||0);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;};
export const escapeHTML = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function defaultDeck(i){return {trackId:i<2?`demo-${i}`:null,position:0,playing:false,rate:1,pitch:0,keyLock:false,reverse:false,slip:false,quantize:true,cuePoint:0,cueOn:false,volume:.82,gain:0,low:0,mid:0,high:0,filter:0,assign:i%2?'B':'A',loopBeats:8,loop:{enabled:false,start:0,end:0},padMode:'cue',fx:{type:'echo',mix:0,beats:.5},locked:false};}
const p=(x,y,w,h,visible=true)=>({x,y,w,h,visible});
export function presetLayout(mode='two'){
  if(mode==='four') return {waves:p(0,0,24,6),deck0:p(0,6,6,30),deck1:p(6,6,6,30),deck2:p(12,6,6,30),deck3:p(18,6,6,30),mixer:p(0,36,12,22),library:p(12,36,12,22),sampler:p(0,58,24,13)};
  if(mode==='focus') return {waves:p(0,0,24,7),deck0:p(0,7,9,27),deck1:p(15,7,9,27),deck2:p(0,56,9,27,false),deck3:p(15,56,9,27,false),mixer:p(9,7,6,27),library:p(0,34,24,22),sampler:p(0,56,24,13,false)};
  return {waves:p(0,0,24,6),deck0:p(0,6,9,27),deck1:p(15,6,9,27),deck2:p(0,51,9,27,false),deck3:p(15,51,9,27,false),mixer:p(9,6,6,27),library:p(0,33,18,18),sampler:p(18,33,6,18)};
}
export function defaultSession(){return {version:VERSION,waveformStyle:'rgb',decks:Array.from({length:4},(_,i)=>defaultDeck(i)),mixer:{master:.75,crossfader:0,curve:'equal-power',headphone:.7,cueMix:0,route:'stereo',masterSink:'default',cueSink:'default',sampler:.65},layout:presetLayout(),preset:'two',layouts:[],selectedDeck:0,selectedTrack:'demo-0',playlist:'all',playlists:[],sampler:Array.from({length:8},()=>null),midiMappings:[],hidMappings:[],midiOutput:'',midiFeedback:false,history:[]};}
export function normalizeSession(raw){
 const s=defaultSession();if(!raw||raw.version!==VERSION)throw new Error('このセッション形式には対応していません。');
 s.waveformStyle=['rgb','3band','deck'].includes(raw.waveformStyle)?raw.waveformStyle:'rgb';
 const bounds={position:[0,86400],rate:[.25,4],pitch:[-12,12],cuePoint:[0,86400],volume:[0,1],gain:[-24,12],low:[-30,12],mid:[-30,12],high:[-30,12],filter:[-1,1],loopBeats:[.125,128]};
 s.decks=s.decks.map((d,i)=>{const r=raw.decks?.[i]||{};for(const [k,b] of Object.entries(bounds))if(r[k]!=null)d[k]=clamp(r[k],...b);for(const k of ['keyLock','reverse','slip','quantize','cueOn','locked'])d[k]=Boolean(r[k]??d[k]);d.trackId=typeof r.trackId==='string'?r.trackId:null;d.playing=false;d.assign=['A','B','THRU'].includes(r.assign)?r.assign:d.assign;d.padMode=['cue','roll','jump'].includes(r.padMode)?r.padMode:'cue';if(r.fx)d.fx={type:['echo','reverb','flanger'].includes(r.fx.type)?r.fx.type:'echo',mix:clamp(r.fx.mix,0,1),beats:clamp(r.fx.beats,.125,4)};d.loop={enabled:!!r.loop?.enabled,start:clamp(r.loop?.start,0,86400),end:clamp(r.loop?.end,0,86400)};if(d.loop.end<=d.loop.start)d.loop.enabled=false;return d;});
 for(const k of ['master','headphone','cueMix','sampler'])s.mixer[k]=clamp(raw.mixer?.[k]??s.mixer[k],0,1);s.mixer.crossfader=clamp(raw.mixer?.crossfader??0,-1,1);s.mixer.curve=['equal-power','linear','cut'].includes(raw.mixer?.curve)?raw.mixer.curve:'equal-power';s.mixer.route=['stereo','split','multi','device'].includes(raw.mixer?.route)?raw.mixer.route:'stereo';for(const k of ['masterSink','cueSink'])if(typeof raw.mixer?.[k]==='string')s.mixer[k]=raw.mixer[k];
 s.preset=['two','four','focus','custom'].includes(raw.preset)?raw.preset:'two';s.layout=normalizeLayout(raw.layout);s.layouts=(Array.isArray(raw.layouts)?raw.layouts:[]).slice(0,30).filter(x=>x?.name).map(x=>({name:String(x.name).slice(0,100),layout:normalizeLayout(x.layout)}));s.selectedDeck=Math.round(clamp(raw.selectedDeck??0,0,3));s.selectedTrack=typeof raw.selectedTrack==='string'?raw.selectedTrack:null;
 s.playlists=(Array.isArray(raw.playlists)?raw.playlists:[]).slice(0,300).filter(x=>x?.id&&x?.name).map(x=>({id:String(x.id),name:String(x.name).slice(0,200),tracks:[...new Set((Array.isArray(x.tracks)?x.tracks:[]).filter(x=>typeof x==='string'))]}));s.playlist=typeof raw.playlist==='string'?raw.playlist:'all';
 s.sampler=s.sampler.map((_,i)=>{let p=raw.sampler?.[i];return p&&typeof p.trackId==='string'?{trackId:p.trackId,label:String(p.label||`SAMPLE ${i+1}`).slice(0,100),start:clamp(p.start,0,86400),duration:clamp(p.duration,.05,30),gain:clamp(p.gain??1,0,1),loop:!!p.loop}:null;});
 s.midiMappings=(Array.isArray(raw.midiMappings)?raw.midiMappings:[]).filter(m=>validTarget(m?.target)).slice(0,1000);s.hidMappings=(Array.isArray(raw.hidMappings)?raw.hidMappings:[]).filter(m=>validTarget(m?.target)).slice(0,1000);s.midiOutput=typeof raw.midiOutput==='string'?raw.midiOutput:'';s.midiFeedback=!!raw.midiFeedback;s.history=(Array.isArray(raw.history)?raw.history:[]).filter(x=>typeof x?.trackId==='string').slice(-500);return s;
}
export function normalizeLayout(raw){const base=presetLayout();for(const id of Object.keys(base)){const r=raw?.[id];if(!r)continue;const w=Math.round(clamp(r.w,4,24));base[id]={x:Math.round(clamp(r.x,0,24-w)),y:Math.round(clamp(r.y,0,200)),w,h:Math.round(clamp(r.h,id==='waves'?4:8,80)),visible:r.visible!==false};}return base;}
export function normalizeTrack(t){if(!t||typeof t.id!=='string'||typeof t.name!=='string')throw new Error('不正なトラックデータです。');const peaks=(Array.isArray(t.peaks)?t.peaks:[]).slice(0,MAX_WAVE_BINS).map(n=>Math.round(clamp(n,0,255)));return {...t,peaks,waveform:normalizeWaveform(t.waveform,peaks.length),id:t.id.slice(0,200),name:t.name.slice(0,500),artist:String(t.artist||'').slice(0,500),comment:String(t.comment||'').slice(0,2000),duration:clamp(t.duration,0,86400),bpm:clamp(t.bpm||120,20,400),gridOffset:clamp(t.gridOffset||0,0,86400),cues:Array.from({length:8},(_,i)=>Number.isFinite(t.cues?.[i])?clamp(t.cues[i],0,t.duration):null),rating:Math.round(clamp(t.rating||0,0,5))};}
export function validTarget(s){return typeof s==='string'&&/^(deck\.[0-3]\.(play|cue|sync|jog|scratch|rate|pitch|volume|gain|low|mid|high|filter|loop|reverse|slip|keyLock|cueOn|fx|hotcue[0-7])|mixer\.(crossfader|master|headphone|cueMix|sampler)|sampler\.[0-7])$/.test(s);}
export function xfadeGains(x,curve='equal-power'){x=clamp(x,-1,1);if(curve==='cut')return [x>.94?(1-x)/.06:1,x<-.94?(1+x)/.06:1];if(curve==='linear')return [(1-x)/2,(1+x)/2];return [Math.cos((x+1)*Math.PI/4),Math.sin((x+1)*Math.PI/4)];}
export function quantize(position,bpm,offset=0){const beat=60/bpm;return Math.max(0,Math.round((position-offset)/beat)*beat+offset);}
export function alignedPosition(position,targetBpm,targetOffset,masterPosition,masterBpm,masterOffset){const beat=60/targetBpm;const phase=mod((masterPosition-masterOffset)/(60/masterBpm),1);return Math.max(0,Math.round((position-targetOffset)/beat-phase)*beat+phase*beat+targetOffset);}
